'use strict';
(()=>{
 const TOKEN='su-ky-auth-token',USER='su-ky-auth-user',SESSION='su-ky-auth-session',STORE='su-ky-progress-v1',V2='kienhoc-progress-v2',META='kienhoc-cloud-meta-v1',OWNER='kienhoc-progress-owner';
 const INFO='kienhoc-info-choices-v1',AI='kienhoc-ai-choices-v1',LESSONS='kienhoc-lessons-v1';
 let identity=readIdentity(),revision=0,ready=false,pulling=false,running=false,dirty=false,timer=0,retry=2000,generation=0,status='local';
 const read=(k,fallback)=>{try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}};
 function readIdentity(){try{const u=JSON.parse(localStorage.getItem(USER));if(!u?.id||u.mock||u.authMode!=='cookie'||!Number.isFinite(u.expiresAt)||u.expiresAt<=Date.now())return null;return {user:u};}catch{return null;}}
 let csrf='';
 const clone=x=>JSON.parse(JSON.stringify(x));
 let meta=read(META,{}),baseline=snapshot(false);
 function changeStatus(value){status=value;document.dispatchEvent(new CustomEvent('kien-cloud-status',{detail:value}));}
 async function api(path,body,authenticated=false,legacyToken,retried=false){const epoch=generation,userId=identity?.user.id;const res=await fetch((window.KIEN_CONFIG?.apiBase||'')+'/api'+path,{method:body===undefined?'GET':'POST',headers:{'X-Kien-Session':'cookie',...(body!==undefined?{'Content-Type':'application/json','X-Kien-CSRF':csrf,...(authenticated&&userId?{'X-Kien-User':userId}:{})}:{}),...(legacyToken?{Authorization:'Bearer '+legacyToken}:{})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(15000)});let data;try{data=await res.json();}catch{throw Error('Máy chủ API chưa được kết nối tại địa chỉ này.');}if(!res.ok){if(res.status===409&&data.code==='ACCOUNT_CHANGED'&&authenticated){await restore();const error=new Error(data.error);error.status=409;error.data=data;throw error;}if(res.status===403&&data.code==='CSRF_REQUIRED'&&authenticated&&body!==undefined&&!retried){const account=await api('/auth/me');if(epoch!==generation||account.user?.id!==userId||identity?.user.id!==userId)throw Error('Tài khoản vừa thay đổi ở tab khác. Hãy tải lại trước khi lưu.');return api(path,body,authenticated,undefined,true);}const error=new Error(data.error||'Không kết nối được máy chủ.');error.status=res.status;error.data=data;throw error;}if(data.csrf)csrf=data.csrf;return data;}
 async function check(){try{const data=await api('/health');return data.service==='kienhoc-api'?data:null;}catch{return null;}}
 function snapshot(stamp=true){const data=read(STORE,KienProgress.blank());data.version=1;data.progress||={};data.bookmarks||=[];data.session??=null;data.prefs||={sound:true,speechRate:.9};const info=read(INFO,{}),ai=read(AI,{}),lessons=read(LESSONS,{});meta.bookmarks||={};meta.ai||={};meta.info||={};meta.lessons||={};if(stamp&&baseline){const now=Date.now();for(const k of new Set([...(baseline.bookmarks||[]),...data.bookmarks])){const value=data.bookmarks.includes(k);if(value!==(baseline.bookmarks||[]).includes(k))meta.bookmarks[k]={value,at:now};}if(JSON.stringify(data.session)!==JSON.stringify(baseline.session))meta.sessionAt=now;if(JSON.stringify(data.prefs)!==JSON.stringify(baseline.prefs))meta.prefsAt=now;if(Object.keys(baseline.progress||{}).length&&!Object.keys(data.progress).length)meta.resetAt=now;
   for(const [type,values] of [['ai',ai],['info',info],['lessons',lessons]])for(const k of new Set([...Object.keys(meta[type]),...Object.keys(values)])){const value=values[k]??(type==='lessons'?false:null);if(value!==meta[type][k]?.value)meta[type][k]={value,at:now};}}
  for(const k of data.bookmarks)meta.bookmarks[k]||={value:true,at:0};for(const [k,value]of Object.entries(ai))meta.ai[k]||={value,at:0};for(const [k,value]of Object.entries(lessons))meta.lessons[k]||={value:!!value,at:0};for(const [k,value]of Object.entries(info))meta.info[k]||={value,at:0};data._sync=clone(meta);const v2=read(V2,null);if(v2?.version===2)data.subjects=Object.fromEntries(['history','ai','information'].map(id=>[id,v2[id]||KienProgress.blank()]));return data;}
 function capture(){const data=snapshot();baseline=clone(data);localStorage.setItem(META,JSON.stringify(meta));return data;}
 function apply(data,switched=false){if(data.subjects)localStorage.setItem(V2,JSON.stringify({version:2,...data.subjects}));else if(switched)localStorage.setItem(V2,JSON.stringify({version:2,history:KienProgress.blank(),ai:KienProgress.blank(),information:KienProgress.blank()}));meta=data._sync||{};const info={},ai={},lessons={};for(const[k,v]of Object.entries(meta.info||{}))if(v.value)info[k]=v.value;for(const[k,v]of Object.entries(meta.ai||{}))if(v.value)ai[k]=v.value;for(const[k,v]of Object.entries(meta.lessons||{}))lessons[k]=!!v.value;localStorage.setItem(STORE,JSON.stringify(data));localStorage.setItem(AI,JSON.stringify(ai));localStorage.setItem(INFO,JSON.stringify(info));localStorage.setItem(LESSONS,JSON.stringify(lessons));localStorage.setItem(META,JSON.stringify(meta));baseline=clone(data);document.dispatchEvent(new CustomEvent('kien-cloud-progress',{detail:{data,switched}}));}
 function cacheCurrent(){const owner=localStorage.getItem(OWNER);if(owner)localStorage.setItem('kienhoc-account-cache:'+owner,JSON.stringify(capture()));}
 async function pull(){if(!identity||pulling)return;const token=identity.token,epoch=generation;pulling=true;changeStatus('syncing');try{const [remote,account]=await Promise.all([api('/progress',undefined,true),api('/auth/me',undefined,true)]);if(epoch!==generation||identity?.token!==token)return;if(account.user.id!==identity.user.id){await signIn(account,!!account.remember);return;}if(JSON.stringify(account.user)!==JSON.stringify(Object.fromEntries(Object.entries(identity.user).filter(([k])=>!['remember','expiresAt','authMode'].includes(k)))))updateUser(account.user);revision=remote.revision;const local=capture();apply(KienProgress.merge(remote.progressData,local));ready=true;dirty=true;retry=2000;}catch(error){if(epoch===generation){changeStatus(error.status===401?'expired':'offline');if(error.status===401)clearIdentity();throw error;}}finally{if(epoch===generation)pulling=false;}if(dirty)await flush();}
 function queue(){try{capture();}catch{changeStatus('storage-error');return;}if(!identity)return;dirty=true;changeStatus('pending');clearTimeout(timer);timer=setTimeout(()=>{if(ready)flush();else pull().catch(scheduleRetry);},800);}
 function scheduleRetry(){if(!identity||!navigator.onLine)return;clearTimeout(timer);timer=setTimeout(()=>{(ready?flush():pull()).catch(scheduleRetry);},retry);retry=Math.min(60000,retry*2);}
 async function flush(){if(!identity||!ready||running||pulling)return;running=true;const epoch=generation,token=identity.token;try{let conflicts=0;while(dirty&&identity?.token===token&&epoch===generation){dirty=false;changeStatus('syncing');const data=capture();try{const result=await api('/progress',{progressData:data,expectedRevision:revision},true);if(epoch!==generation)return;revision=result.revision;retry=2000;}catch(error){if(epoch!==generation)return;dirty=true;if(error.status===409&&error.data?.code!=='ACCOUNT_CHANGED'&&conflicts++<4){revision=error.data.revision;apply(KienProgress.merge(error.data.progressData,capture()));continue;}throw error;}}if(epoch===generation){changeStatus('synced');cacheCurrent();}}catch(error){if(epoch===generation){changeStatus(error.status===401?'expired':'offline');if(error.status===401)clearIdentity();else scheduleRetry();}}finally{if(epoch===generation)running=false;}}
 function clearIdentity(){csrf='';generation++;identity=null;ready=pulling=running=false;clearTimeout(timer);localStorage.removeItem(TOKEN);localStorage.removeItem(USER);sessionStorage.removeItem(SESSION);document.dispatchEvent(new Event('kien-auth-change'));}
 async function signIn(result,remember){if(result?.token)result=await api('/auth/exchange',{remember},false,result.token);if(result?.session!=='cookie'||!result.user?.id)throw Error('Phản hồi đăng nhập không hợp lệ.');csrf=result.csrf;const next={...result.user,remember:result.remember??remember,authMode:'cookie',expiresAt:Date.now()+result.expiresIn*1000};const owner=localStorage.getItem(OWNER),switched=!!owner&&owner!==next.id;cacheCurrent();generation++;clearTimeout(timer);ready=pulling=running=false;dirty=false;revision=0;
  // Never merge another account's browser snapshot into this account.
  if(switched)apply(read('kienhoc-account-cache:'+next.id,KienProgress.blank()),true);
  identity={user:next};localStorage.setItem(OWNER,next.id);localStorage.setItem(USER,JSON.stringify(next));localStorage.removeItem(TOKEN);if(!remember)sessionStorage.setItem(SESSION,next.id);else sessionStorage.removeItem(SESSION);document.dispatchEvent(new Event('kien-auth-change'));
  try{await pull();await flush();return status==='synced';}catch{scheduleRetry();return false;}
 }
 async function signOut(){const active=identity;cacheCurrent();if(active){await flush();try{await api('/auth/logout',{},true);}catch(error){if(error.status!==401)throw error;}}clearIdentity();changeStatus('local');}
 function updateUser(user){if(!identity||user?.id!==identity.user.id)return;identity.user={...identity.user,...user};localStorage.setItem(USER,JSON.stringify(identity.user));document.dispatchEvent(new Event('kien-auth-change'));}
 window.KienCloud={api,check,queue,flush,pull,signIn,signOut,updateUser,getUser:()=>identity?.user||null,getStatus:()=>status};
 window.addEventListener('online',()=>{if(identity)(ready?flush():pull()).catch(scheduleRetry);else restore().catch(scheduleRetry);});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)flush();else if(identity&&!running&&!pulling)pull().catch(scheduleRetry);});
 window.addEventListener('storage',e=>{if(e.key===TOKEN||e.key===USER){const next=readIdentity();if(next?.user.id!==identity?.user.id){generation++;identity=next;ready=pulling=running=false;clearTimeout(timer);document.dispatchEvent(new Event('kien-auth-change'));if(identity)restore().catch(scheduleRetry);}else if(next&&e.key===USER){identity=next;document.dispatchEvent(new Event('kien-auth-change'));}}else if([STORE,V2,AI,INFO,LESSONS].includes(e.key))queue();});
 async function restore(){const epoch=generation;let legacy=localStorage.getItem(TOKEN),previous=read(USER,null);try{let account;
  if(legacy&&previous?.id&&(previous.remember||sessionStorage.getItem(SESSION)===previous.id)){try{account=await api('/auth/exchange',{remember:!!previous.remember},false,legacy);}catch(error){if(error.status!==401)throw error;account=await api('/auth/me');}}
  else account=await api('/auth/me');
  if(epoch!==generation)return;
  await signIn(account,!!account.remember);
 }catch(error){if(epoch===generation&&error.status===401)clearIdentity();else if(epoch===generation){changeStatus('offline');throw error;}}}
 document.addEventListener('DOMContentLoaded',()=>{restore().catch(scheduleRetry);});
})();
